#![no_main]
use these_macros_should_be_illegal::forall;
pub struct Pixel(pub(crate) u8, pub(crate) u8, pub(crate) u8);
pub struct Point {
    ///Field `Point::x` generated by `forall`.
    pub x: f32,
    ///Field `Point::y` generated by `forall`.
    pub y: f32,
}
pub struct Channels {
    ///One channel of the shared triple.
    ///Intensity of the red channel.
    pub red: u8,
    ///One channel of the shared triple.
    pub green: u8,
    ///One channel of the shared triple.
    pub blue: u8,
}
pub struct Buckets<T>
where
    T: Clone,
{
    ///Field `Buckets::small` generated by `forall`.
    pub small: Vec<T>,
    ///Field `Buckets::large` generated by `forall`.
    pub large: Vec<T>,
}
pub struct Window {
    ///One shared field.
    pub width: u32,
    ///One shared field.
    pub(crate) height: u32,
}
pub enum Response {
    Redirect(u16, String),
    Error(&'static str, u16, String),
}
pub enum Request {
    Read {
        ///Field `Request::Read::code` generated by `forall`.
        code: u16,
        ///Field `Request::Read::path` generated by `forall`.
        path: String,
    },
    Write {
        payload: u8,
        ///Field `Request::Write::code` generated by `forall`.
        code: u16,
        ///Field `Request::Write::path` generated by `forall`.
        path: String,
    },
}
pub enum Stage {
    ///One stage of the pipeline.
    Parse,
    ///One stage of the pipeline.
    Lower { depth: usize },
}
